const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sePoint = ee.Geometry.Point(121.96499287870442, 24.83594812988359);
  const nwPoint = ee.Geometry.Point(121.93452298429524, 24.84607374884142);
  const date = '2021-09-29';
  const bufferSize = 100; // meters for region of interest
  const scale = 10; // Sentinel-2 Blue band resolution

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(sePoint.union(nwPoint))
    .filter(ee.Filter.lt('CLOUD_COVERAGE_ASSESSMENT', 20)); // Filter for relatively clear images

  const collectionSize = await collection.size().getInfo();

  if (collectionSize === 0) {
    // Try expanding date range
    collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterDate(ee.Date(date).advance(-2, 'day'), ee.Date(date).advance(3, 'day'))
      .filterBounds(sePoint.union(nwPoint))
      .filter(ee.Filter.lt('CLOUD_COVERAGE_ASSESSMENT', 20));

    if (await collection.size().getInfo() === 0) {
      console.log("C1: No images found for the specified date and location.");
      return;
    }
  }

  // Cloud masking function for Sentinel-2 SR
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(
                 qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000) // Scale to surface reflectance
                .select(['B2', 'B3', 'B4', 'B8']); // Select relevant bands
  }

  const image = collection.sort('CLOUD_COVERAGE_ASSESSMENT').first().map(maskS2clouds);

  const imageId = await image.id().getInfo();
  const cloudCoverage = await ee.Image(collection.sort('CLOUD_COVERAGE_ASSESSMENT').first()).get('CLOUD_COVERAGE_ASSESSMENT').getInfo();
  console.log(`Image selected: ${imageId} (Cloud Cover: ${cloudCoverage}%)`);

  // 3. Processing & Calculation
  const seRegion = sePoint.buffer(bufferSize);
  const nwRegion = nwPoint.buffer(bufferSize);

  const reducer = ee.Reducer.mean();
  const band = 'B2'; // Sentinel-2 Blue band

  const getMeanReflectance = async (geom, name) => {
    const stats = await image.reduceRegion({
      reducer: reducer,
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const value = stats[band];

    // Validate pixel count
    const pixelCount = await image.select(band).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).get(band).getInfo();

    return { value, pixelCount, name };
  };

  const seResult = await getMeanReflectance(seRegion, 'SE');
  const nwResult = await getMeanReflectance(nwRegion, 'NW');

  // 4. Validation & Final Answer
  if (seResult.pixelCount === 0 || nwResult.pixelCount === 0) {
    console.log(`C2: No valid pixels remaining after cloud masking for SE: ${seResult.pixelCount}, NW: ${nwResult.pixelCount}.`);
    return;
  }

  if (seResult.value === null || nwResult.value === null) {
    console.log(`C3: Calculation failure - one or both reflectance values are null. SE: ${seResult.value}, NW: ${nwResult.value}.`);
    return;
  }

  const seBlue = seResult.value;
  const nwBlue = nwResult.value;

  console.log(`SE water blue reflectance: ${seBlue.toFixed(4)} (Pixels: ${seResult.pixelCount})`);
  console.log(`NW water blue reflectance: ${nwBlue.toFixed(4)} (Pixels: ${nwResult.pixelCount})`);

  if (seBlue > nwBlue) {
    console.log("A"); // Southeastern water is lighter blue (higher B2 reflectance)
  } else {
    console.log("B"); // Southeastern water is not lighter blue
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
